import json,datetime
from pathlib import Path
p=Path(__file__).parent; a=json.loads((p/'candidates.json').read_text());cells=json.loads((p/'coverage.json').read_text());now=datetime.datetime.now(datetime.timezone.utc).isoformat()
items=[('Proposal 5 – Right to Action by Written Consent',['John Chevedden'],2014,'eBay 2014 Proxy Statement','https://www.sec.gov/Archives/edgar/data/1065088/000119312514112751/d661450ddefc14a.htm#toc764322_10','Actual shareholder proposal requests board action and supplies supporting argument; contained in company proxy.','proposal'),('Producer Responsibility for Packaging',['Cedar Tree Foundation','As You Sow'],2012,'Kraft Foods Preliminary Proxy Statement, Item 6','https://www.sec.gov/Archives/edgar/data/1103982/000119312512129962/d294291dpre14a.htm','An actual shareholder proposal asks the board to assess a packaging responsibility policy; As You Sow represented the foundation.','proposal'),('Issuance of a Sustainability Report to Shareholders',['Calvert Asset Management Company, Inc.'],2007,'Pentair Preliminary Proxy Statement, Proposal 5','https://www.sec.gov/Archives/edgar/data/77360/000095013707003224/c12468pre14a.htm','An actual shareholder proposal requests a sustainability report, with supporting statement and board response.','proposal'),('The Internet Tidal Wave',['Bill Gates'],1995,'Microsoft internal memorandum; U.S. Department of Justice Government Exhibit 20','https://www.justice.gov/sites/default/files/atr/legacy/2006/03/03/20.pdf','Internal strategic direction memo communicates decisions and proposed actions; not a demonstrated request-for-decision memo.','decision_memo')]
for title,authors,year,venue,url,basis,form in items:
 c={'id':'business_'+str(len(a)+1).zfill(3),'field':'business_management','form_id':form,'title':title,'authors':authors,'year':year,'venue':venue,'doi':None,'doi_aliases':[],'stable_url':url,'volume':None,'issue':None,'pages':None,'form_basis':basis,'form_status':'conditional analogue: direction memorandum' if form=='decision_memo' else 'actual shareholder proposal in corporate SEC filing','selection_signal_type':'public primary-source institutional record','selection_evidence':'US official court exhibit; Microsoft identifies this memo in its corporate history' if form=='decision_memo' else 'Actual corporate proxy proposal presented as a source example; wide readership or citation prominence not established','selection_source_url':'https://news.microsoft.com/microsoft-50/' if form=='decision_memo' else url,'citation_count':None,'citation_provider':None,'citation_snapshot':None,'verification_status':'verified against primary document metadata and text','verification_sources':[{'provider':'U.S. government archive of original document','query_url':url,'retrieved_at':now}],'date_notes':'original document, through 2014','copy_status':'public source text located; complete copy not separately retrieved or assessed','retrieval_locator':f'{title}; {", ".join(authors)}; {venue}, {year}; {url}','why_this_example':basis,'limitations':'No claim of citation or readership prominence; an embedded proposal is not the complete proxy statement.' if form=='proposal' else 'Direction-setting document rather than a decision request; not counted.'};a.append(c)
 if form=='proposal':
  cell=next(x for x in cells if x['form_id']==form);cell['candidate_ids'].append(c['id']);cell['provided']+=1;cell['status']='three_targets' if cell['provided']==3 else 'partial_gap';cell['reason']='Three distinct original shareholder proposals in corporate proxy filings; selected as practical form examples without readership evidence.'
 else:
  cell=next(x for x in cells if x['form_id']==form);cell['status']='conditional_analogue';cell['reason']='A 1995 executive strategy memo is preserved as an uncounted analogue; its decision-request form is not established.'
(p/'candidates.json').write_text(json.dumps(a,indent=2,ensure_ascii=False)+'\n');(p/'coverage.json').write_text(json.dumps(cells,indent=2,ensure_ascii=False)+'\n');print('candidates',len(a),'placements',sum(c['provided'] for c in cells))
